using EnterpriseSaaS.SharedKernel;
namespace EnterpriseSaaS.Tenant.Domain;

public interface ITenantOwned { Guid TenantId { get; } }
public sealed class Customer : AggregateRoot, ITenantOwned { private Customer() { } public Customer(Guid tenantId, string name, string email) { TenantId = tenantId; Name = name; Email = email; } public Guid TenantId { get; private set; } public string Name { get; private set; } = null!; public string Email { get; private set; } = null!; }
public sealed class Product : AggregateRoot, ITenantOwned { private Product() { } public Product(Guid tenantId, string sku, string name, decimal price) { TenantId = tenantId; Sku = sku; Name = name; Price = price; } public Guid TenantId { get; private set; } public string Sku { get; private set; } = null!; public string Name { get; private set; } = null!; public decimal Price { get; private set; } }
public sealed class Order : AggregateRoot, ITenantOwned { private readonly List<OrderLine> _lines = []; private Order() { } public Order(Guid tenantId, Guid customerId) { TenantId = tenantId; CustomerId = customerId; } public Guid TenantId { get; private set; } public Guid CustomerId { get; private set; } public DateTimeOffset CreatedAt { get; private set; } = DateTimeOffset.UtcNow; public IReadOnlyCollection<OrderLine> Lines => _lines; public decimal Total => _lines.Sum(x => x.Quantity * x.UnitPrice); public void AddLine(Guid productId, int quantity, decimal unitPrice) { if (quantity <= 0) throw new ArgumentOutOfRangeException(nameof(quantity)); _lines.Add(new OrderLine(productId, quantity, unitPrice)); } }
public sealed class OrderLine { private OrderLine() { } internal OrderLine(Guid productId, int quantity, decimal unitPrice) { ProductId = productId; Quantity = quantity; UnitPrice = unitPrice; } public int Id { get; private set; } public Guid ProductId { get; private set; } public int Quantity { get; private set; } public decimal UnitPrice { get; private set; } }
public sealed class Invoice : AggregateRoot, ITenantOwned { public Guid TenantId { get; init; } public Guid OrderId { get; init; } public decimal Amount { get; init; } public DateTimeOffset IssuedAt { get; init; } = DateTimeOffset.UtcNow; }
public interface IProductRepository : IRepository<Product> { Task<IReadOnlyList<Product>> ListAsync(CancellationToken cancellationToken = default); }
